from pathlib import Path
root=Path('outputs/GoblinSlashFX')
data=(root/'preview-data.json').read_text(encoding='utf-8').replace('<','\\u003c')
import base64
ref='data:image/png;base64,'+base64.b64encode((root/'trajectory-reference-study.png').read_bytes()).decode()
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>哥布林斩击 · 参考轨迹与特效</title><style>:root{color-scheme:dark;font-family:system-ui,sans-serif}body{margin:0;background:#101b23;color:#ecf3f6}main{max-width:1300px;margin:auto;padding:25px}h1{font-size:28px;margin-bottom:8px}p{line-height:1.7;color:#bed0da}button,select,a{padding:10px 15px;margin:5px 5px 5px 0;border:1px solid #426474;border-radius:7px;background:#214653;color:#eef8f7;text-decoration:none;cursor:pointer}label{display:inline-block;margin:10px}.views{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,450px),1fr));gap:18px;margin-top:20px}section{border:1px solid #385663;background:#1c303c;border-radius:10px;padding:16px}h2{font-size:18px;margin:4px 0 8px}canvas{width:100%;height:auto;image-rendering:pixelated;border-radius:8px}.info{font-variant-numeric:tabular-nums;font-size:14px}#scrub{width:min(700px,90vw)}summary{cursor:pointer;padding:14px}img{max-width:100%}.note{color:#dfc58f;font-size:14px}ul{line-height:1.9;color:#bfd0d9}</style>
<main><h1>哥布林斩击 · 参考轨迹与特效</h1><p>按你提供的十帧轨迹重做：后引蓄力 → 过顶向前斩下 → 接触闪光 → 碎光消散 → 收剑。<br>保留绿皮哥布林与加长后的剑，银白刀光集中在第5–6帧，金色碎光在第7–8帧衰减。</p>
<button id="play">播放两版</button><button id="restart">回到开头</button><button id="prev">上一格</button><button id="next">下一格</button><select id="speed" aria-label="播放倍率"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option></select><label><input id="loop" type="checkbox">重复预览</label><label><input id="onion" type="checkbox">前帧叠影</label><label><input id="silhouette" type="checkbox">剪影</label><select id="bg" aria-label="背景"><option value="#263b47">深灰</option><option value="#d4d3c9">浅灰</option></select><p id="time" class="info"></p><input id="scrub" aria-label="动作时间" type="range" min="0" max="999" value="0"><span class="note"> 两版同为1秒；仅预览统一体高与脚下位置，不修改PNG。</span>
<div class="views"><section><h2>上一版 · 无特效，8姿势</h2><canvas id="old" width="560" height="450"></canvas><p id="oldInfo" class="info"></p></section><section><h2>新版 · 参考轨迹＋刀光，10姿势</h2><canvas id="new" width="560" height="450"></canvas><p id="newInfo" class="info"></p></section></div>
<h2>这次补回的力度表现</h2><ul><li>蓄力先把剑引向身后，再通过头顶向前斩下。</li><li>银白斩击弧跟着剑的运动展开，命中区域增加一次短暂黄白闪光。</li><li>挥出后大弧迅速消失，只留少量碎光；待机和蓄力期间不挂特效。</li></ul>
<details><summary>你提供的轨迹参考：十帧放大对照</summary><img src="__REF__" alt="十帧剑轨迹参考"></details><details><summary>新版逐帧联系表</summary><img src="review/contact-sheet.png" alt="新版十帧联系表"></details>
<p class="note">独立动作候选，尚未替换游戏资产。特效当前合成在PNG内；身体/握点与剑长仍有轻微生成漂移，第9帧持械透视需继续核对。力量感由实际播放评审，技术测试不等于美术验收。</p></main>
<script id="data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let t=0,playing=false,last=null,images={};const starts={};
for(const key of ['old','new']){let sum=0;starts[key]=d[key].frames.map(f=>{const v=sum;sum+=f.duration;return v})}
function index(key){let i=0;while(i+1<d[key].frames.length&&starts[key][i+1]<=t)i++;return i}
function drawPose(ctx,key,i,alpha){const f=d[key].frames[i],s=d[key].scale;ctx.globalAlpha=alpha;ctx.drawImage(images[key][i],240-f.anchor[0]*s,390-f.anchor[1]*s,images[key][i].width*s,images[key][i].height*s);ctx.globalAlpha=1}
function render(){if(!images.old||!images.new)return;for(const key of ['old','new']){const ctx=$(key).getContext('2d'),i=index(key);ctx.clearRect(0,0,560,450);if($('onion').checked&&i>0)drawPose(ctx,key,i-1,.22);drawPose(ctx,key,i,1);if($('silhouette').checked){ctx.globalCompositeOperation='source-in';ctx.fillStyle='#090d10';ctx.fillRect(0,0,560,450);ctx.globalCompositeOperation='source-over'}ctx.strokeStyle='#5fbeac';ctx.beginPath();ctx.moveTo(0,390.5);ctx.lineTo(560,390.5);ctx.moveTo(240.5,384);ctx.lineTo(240.5,397);ctx.stroke();ctx.globalCompositeOperation='destination-over';ctx.fillStyle=$('bg').value;ctx.fillRect(0,0,560,450);ctx.globalCompositeOperation='source-over';$(key+'Info').textContent=`${i+1} / ${d[key].frames.length} · ${d[key].frames[i].label}`} $('scrub').value=Math.floor(t);$('time').textContent=`${Math.floor(t)} ms / 1000 ms`}
function pause(){playing=false;$('play').textContent='播放两版'}
$('play').onclick=()=>{if(t>=999&&!playing)t=0;playing=!playing;last=null;$('play').textContent=playing?'暂停':'播放两版';render()};$('restart').onclick=()=>{pause();t=0;render()};$('prev').onclick=()=>{pause();t=Math.max(0,Math.floor(t/100)*100-100);render()};$('next').onclick=()=>{pause();t=Math.min(999,Math.floor(t/100)*100+100);render()};$('scrub').oninput=()=>{pause();t=Number($('scrub').value);render()};['onion','silhouette','bg'].forEach(id=>$(id).onchange=render);
function tick(now){if(last===null)last=now;const delta=Math.min(now-last,200);last=now;if(playing){t+=delta*Number($('speed').value);if(t>=1000){if($('loop').checked)t%=1000;else{t=999;pause()}}render()}requestAnimationFrame(tick)}
Promise.all(['old','new'].map(async key=>{images[key]=await Promise.all(d[key].frames.map(f=>new Promise((resolve,reject)=>{const i=new Image;i.onload=()=>resolve(i);i.onerror=reject;i.src=f.data})))})).then(()=>{render();window.slashFXReview={ready:true,get time(){return t},get frame(){return index('new')},data:d};requestAnimationFrame(tick)}).catch(()=>{$('time').textContent='帧加载失败'});
</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',data).replace('__REF__',ref),encoding='utf-8')
